}
@keyframes Toastify__slideOutLeft { 
  0% { transform: translate3d(0, var(--y), 0); }
  100% { visibility: hidden; transform: translate3d(-110%, var(--y), 0); }
}
@keyframes Toastify__slideOutDown { 
  0% { transform: translate3d(0, var(--y), 0); }
